@r1 syntax.relation marker="so" from=$c1 to=$c2
@n3 syntax.nominal head="it"
@c2 syntax.clause form=declarative verb="is" subject=$n3
@r2 syntax.relation marker="in line with" from=$c2 to=$n4
@n4 syntax.nominal head="Barn"

sop:
@c1 syntax.clause form=imperative modifier="maybe" verb="lower" complement=$n1
@n1 syntax.nominal head="Hill"
@r1 syntax.relation marker="until" from=$c1 to=$c2
@n2 syntax.nominal head="it"
@c2 syntax.clause form=declarative verb="is" modifier="square" subject=$n2
@r2 syntax.relation marker="with" from=$c2 to=$n3
@n3 syntax.nominal head="Tree"

alt:
@c1 syntax.clause form=fragment modifier="maybe" modifier="lower" complement=$n1
@n1 syntax.nominal head="Hill"
@r1 syntax.relation marker="until" from=$c1 to=$c2
@n2 syntax.nominal head="it"
@c2 syntax.clause form=declarative verb="is" subject=$n2 complement=$n3
@n3 syntax.nominal head="square"
@r2 syntax.relation marker="with" from=$n3 to=$n4
@n4 syntax.nominal head="Tree"
